def mean_or_none(values):
    if not values:
        return None
    return sum(values) / len(values)

print(mean_or_none([3, 5, 10]))
print(mean_or_none([]))
def summarize_sample(values):
    count = len(values)
    if count == 0:
        return {"count": 0, "mean": None, "median": None}
    ordered = sorted(values)
    mid = count // 2
    if count % 2 == 1:
        median = ordered[mid]
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2
    return {"count": count, "mean": sum(values) / count, "median": median}

print(summarize_sample([3, 5, 10]))
print(summarize_sample([12, 2, 8, 6]))
print(summarize_sample([]))
